def write_csv(path: Path, records: list[dict[str, object]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", newline="", encoding="utf-8") as f:
        w=csv.DictWriter(f, fieldnames=list(records[0]), lineterminator="\n"); w.writeheader(); w.writerows(records)
def rows(path: Path):
    with path.open(newline="", encoding="utf-8-sig") as f: return list(csv.DictReader(f))
def sha(path: Path): return hashlib.sha256(path.read_bytes()).hexdigest()
def manifest(directory: Path):
    write_csv(directory/"file-manifest.csv", [{"relative_path":p.relative_to(directory).as_posix(),"sha256":sha(p),"bytes":p.stat().st_size,"warning":WARNING} for p in sorted(directory.rglob("*")) if p.is_file() and p.name!="file-manifest.csv"])
def table(rs):
    fs=list(rs[0]); h="".join(f"<th>{html.escape(x.replace('_',' '))}</th>" for x in fs); b="".join("<tr>"+"".join(f"<td>{html.escape(str(r.get(x,'')))}</td>" for x in fs)+"</tr>" for r in rs); return f"<div class='scroll'><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>"

