      {"source_id":"PAD-SRC-002","manufacturer":"Rogers Corporation","identity":"PORON availability brochure; product 2300327","document":"PORON polyurethane product availability brochure","revision_or_date":"current brochure; checked 2026-08-12","official_url":"https://www.rogerscorp.com/-/media/project/rogerscorp/documents/elastomeric-material-solutions/poron/english/product-availability/17-082-poron-polyurethanes-product-availability-brochure.pdf","verified":"2300327 listed as 0.61 mm supported roll product","boundary":"current quote, minimum order, lot and CoC remain open","state":"COMMERCIAL REFERENCE / QUOTE REQUIRED","warning":WARNING},
