      {"case_id":"PAD-LC-002","case":"30 deg/s kinetic sensitivity","formula":"0.5*I_eff*omega^2","inputs":"same unaccepted I_eff; omega=30 deg/s","result":f"{e30:.9f} J","disposition":"SENSITIVITY ONLY; 30 DEG/S NOT RELEASED","required_successor":"fault/overspeed allocation and physical verification","warning":WARNING},
