    rd=ROOT/"README.md"; tx=rd.read_text(encoding="utf-8"); mk="## Start here\n\n"; links="- [R275 J2 soft-contact pad candidate](docs/hr-v0-j2-soft-contact-pad-p0.1.md)\n- [R275 independent review request](docs/reviews/2026-08-12-r275-independent-review-request.md)\n- [R275 validation record](docs/reviews/2026-08-12-r275-validation-record.md)\n- [Interactive R275 pad guide](release/hr-v0/j2-soft-contact-pad-p0.1/index.html)\n- [Interactive configuration reconciliation P0.39](release/hr-v0/configuration-reconciliation-p0.39/index.html)\n"; tx=tx if links.splitlines()[0] in tx else tx.replace(mk,mk+links); tx=tx.replace("Two hundred seventy-four rounds are complete: R01-R274.","Two hundred seventy-five rounds are complete: R01-R275."); rd.write_text(tx,encoding="utf-8")
    hd=ROOT/"docs/handoff-current.md"; old=hd.read_text(encoding="utf-8"); block=f"R275 J2 soft-contact pad boundary: **`{IDENT}` names Rogers 2300327 only as an unselected sacrificial contact/noise/rebound pad ahead of the metal backup. Motor-work uncertainty dominates nominal kinetic energy; twelve physical/qualified holds and zero work authority remain.**\n\n"; hd.write_text(old if old.startswith("R275 J2 soft-contact pad boundary:") else block+old,encoding="utf-8")
